L000516	\section{Background equations}
L000517	
L000518	We consider a perfect fluid in a homogeneous, isotropic universe whose stress-energy tensor can be written as
L000519	\begin{equation}
L000520	    \overline{T}^\mu_{\ \nu} = (\overline{\rho} + \overline{p})\overline{u}^\mu \overline{u}_\nu - \overline{p}\delta^\mu_\nu,
L000521	\end{equation}
L000522	where $\overline{u}_\mu = a\delta^0_\mu$ and $\overline{u}^\mu = a^{-1}\delta_0^\mu$. The Einstein field equations in this background lead to the usual Friedmann and continuity equations:
L000523	\begin{equation}
L000524	    H^2 = \frac{8\pi G}{3}\overline{\rho}, \quad
L000525	    \dot{H} = -\frac{3(1+\omega)}{2}H^2, \quad
L000526	    \dot{\overline{\rho}} =-3(1+\omega)H\overline{\rho},
L000527	\end{equation}
L000528	where $H \equiv \dot{a}/a$.
L000529	Expressing time in terms of the conformal variable $\eta$, with $\mathrm{d}t/\mathrm{d}\eta = a(\eta)$, the above relations become:
L000530	\begin{equation}
L000531	\label{eq:Friedmann_comoving}
L000532	    \mathcal{H}^2 = \frac{8\pi G}{3}\overline{\rho}a^2, \quad
L000533	    \mathcal{H}' =-\frac{1 + 3\omega}{2}\mathcal{H}^2, \quad
L000534	    \overline{\rho}' =- 3(1+\omega)\mathcal{H}\overline{\rho} ,
L000535	\end{equation}
L000536	where $\mathcal{H} \equiv a'/a$ is the comoving Hubble factor and $\omega$ is the equation of state of the universe
L000537	\begin{equation}
L000538	\label{eq:EoS}
L000539	\omega~\equiv~ \overline{p} /\overline{\rho}.
L000540	\end{equation}
L000541	Integration of the continuity and Friedmann equation for constant $\omega$ give
L000542	\begin{equation}
L000543	    \overline{\rho} \propto a^{-3(1+\omega)},\qquad \qquad
L000544	    a \propto t^{\,\frac{2}{3(1+\omega)}},\qquad \textrm{and}\qquad
L000545	    a \propto \eta^{\,\frac{2}{1+3\omega}}.
L000546	\end{equation}
L000547	Useful relationships between dot and prime derivatives include:
L000548	\begin{equation}
L000549	    H = \frac{\mathcal{H}}{a}, \quad
L000550	    \dot{H} = \frac{\mathcal{H}'}{a^2} - \frac{\mathcal{H}^2}{a^2}, \quad
L000551	    \dot{F} = \frac{F'}{a}, \quad
L000552	    \ddot{F} = \frac{F''}{a^2} - H\frac{F'}{a},
L000553	\end{equation}
L000554	where $F$ is an arbitrary function.
L000555	
L000556	
L000557	\section{Cosmological Scalar Perturbation Theory}
L000558	
L000559	We briefly review the theory of linear cosmological scalar perturbations and the associated gauge-invariant variables used throughout this work.
L000560	This framework provides the basis for our analysis of perturbations generated during first-order phase transitions.
L000561	
L000562	\subsection{Gauge-invariant linear perturbations}
L000563	
L000564	\textbf{Linear metric perturbations ---}
L000565	The line element with linear perturbations around a flat FLRW metric can be written as:
L000566	\begin{equation}
L000567	    \mathrm{d}s^2
L000568	    =
L000569	    a^2 \Bigl[
L000570	    -\bigl(1 + 2A\bigr)\,\mathrm{d}\eta^2
L000571	    + 2\,B_i\,\mathrm{d}x^i\,\mathrm{d}\eta
L000572	    + \bigl(\delta_{ij} + h_{ij}\bigr)\,\mathrm{d}x^i\,\mathrm{d}x^j
L000573	    \Bigr].
L000574	\end{equation}
L000575	We follow the notations of Ref.~\cite{Peter:2013avv,Baumann:2022mni}.
L000576	The quantity $B_i$ can be split into a gradient plus a divergence-free component:
L000577	\begin{equation}
L000578	    B_i = \partial_i B + \hat{B}_i,
L000579	\end{equation}
L000580	and the symmetric perturbation $h_{ij}$ can be further decomposed into scalar, vector, and tensor contributions:
L000581	\begin{equation}
L000582	    h_{ij} = 2C\delta_{ij}
L000583	    + 2\partial_{\langle i}\partial_{j\rangle}E
L000584	    + 2\partial_{(i}\hat{E}_{j)}
L000585	    + \hat{E}_{ij}
L000586	\end{equation}
L000587	where $\partial_{\langle i}\partial_{j\rangle} E \equiv (\partial_i\partial_j - \tfrac{1}{3}\delta_{ij}\nabla^2)E$ and $\partial_{(i} \hat{E}_{j)}
L000588	= \frac{1}{2} \left( \partial_i \hat{E}_j + \partial_j \hat{E}_i \right)$. The “hatted” functions ($\hat{B}_i$, $\hat{E}_i$, $\hat{E}_{ij}$) are divergence-free, while $\hat{E}_{ij}$ is also traceless. Overall, the ten metric degrees of freedom decompose into four scalars ($A,B,C,E$), four vector components ($\hat{B}_i, \hat{E}_i$), and two tensor modes ($\hat{E}_{ij}$).
L000589	Popular gauge choices are, e.g.~\cite{Kodama:1984ziu}:
L000590	\begin{enumerate}
L000591	    \item \textit{Spatially-Flat gauge} ($C=E=0$)
L000592	    \begin{equation}
L000593	    \label{eq:SF_gauge}
L000594	        \mathrm{d}s^2
L000595	        =
L000596	        a^2 \bigl[
L000597	        -(1 + 2A)\,\mathrm{d}\eta^2
L000598	        + 2\,B_i\,\mathrm{d}x^i\,\mathrm{d}\eta
L000599	        + \mathrm{d}\mathbf{x}^2
L000600	        \bigr].
L000601	    \end{equation}
L000602	
L000603	    \item \textit{Newtonian gauge} ($B=E=0$)
L000604	    \begin{equation}
L000605	    \label{eq:Newtonian_gauge}
L000606	        \mathrm{d}s^2
L000607	        =
L000608	        a^2 \bigl[
L000609	        -(1 + 2A)\,\mathrm{d}\eta^2
L000610	        + (1 + 2C)\,\mathrm{d}\mathbf{x}^2
L000611	        \bigr].
L000612	    \end{equation}
L000613	
L000614	    \item \textit{Comoving gauge} ($v + B = 0,~ E=0$)
L000615	    \begin{equation}
L000616	    \label{eq:Comoving_gauge}
L000617	        \mathrm{d}s^2
L000618	        =
L000619	        a^2\bigl[
L000620	        -(1 + 2A)\,\mathrm{d}\eta^2
L000621	        + 2\,B_i\,\mathrm{d}x^i\,\mathrm{d}\eta
L000622	        + (1 + 2C)\,\mathrm{d}\mathbf{x}^2
L000623	        \bigr].
L000624	    \end{equation}
L000625	    \begin{comment}
L000626	    \item \textbf{Synchronous gauge} ($A=B=0$)
L000627	    \begin{equation}
L000628	        \mathrm{d}s^2
L000629	        =
L000630	        a^2 \Bigl[
L000631	        \mathrm{d}\eta^2
L000632	        - \bigl(\delta_{ij} + 2C\delta_{ij} + 2\partial_{\langle i}\partial_{j\rangle}E \bigr)\,\mathrm{d}\mathbf{x}^2
L000633	        \Bigr].
L000634	    \end{equation}
L000635	    \end{comment}
L000636	\end{enumerate}
L000637	
L000638	\textbf{Linear matter perturbations ---}
L000639	Starting from
L000640	$T^\mu{}_\nu=(\rho+p)u^\mu u_\nu+p\,\delta^\mu{}_\nu+\Sigma^\mu{}_\nu$,
L000641	the linear perturbation reads~\cite{Peter:2013avv,Baumann:2022mni}
L000642	\begin{equation}
L000643	\delta T^\mu{}_\nu
L000644	=(\delta\rho+\delta p)\,\overline{u}^\mu\overline{u}_\nu
L000645	+(\overline{\rho}+\overline{p})\big(\delta u^\mu\overline{u}_\nu+\overline{u}^\mu\delta u_\nu\big)
L000646	-\delta p\,\delta^\mu{}_\nu-\Sigma^\mu{}_\nu,
L000647	\end{equation}
L000648	where $\Sigma^\mu{}_\nu$ is the first order anisotropic stress.
L000649	The unit norm $u^\mu u_\mu=\overline{u}^\mu \overline{u}_\mu=-1$ implies
L000650	\begin{equation}
L000651	\delta g_{\mu\nu}\overline{u}^\mu \overline{u}^\nu + 2\overline{u}_\mu\delta u^\mu=0.
L000652	\end{equation}
L000653	Using $\overline{u}^\mu=a^{-1}\delta^\mu_0$ and $\delta g_{00}=-2a^2A$, we get $\delta u^0=-Aa^{-1}$.
L000654	Parametrizing the spatial velocity by $\delta u^i=v^i/a$, the 4-velocity reads
L000655	\begin{equation}
L000656	u^\mu=a^{-1}(1-A,\,v^i),\qquad
L000657	u_\mu=a(-(1+A),\,v_i+B_i),
L000658	\end{equation}
L000659	where we used $u_\alpha=g_{\alpha\beta}u^\beta$ and the convention $v_i=\delta_{ij}v^j$. By definition, the anisotropic stress is purely spatial in the fluid rest
L000660	frame and therefore satisfies $\Sigma^\mu{}_\nu u^\nu=0$ and
L000661	$\Sigma^\mu{}_\mu=0$.
L000662	We deduce that the perturbed stress-energy components are:
L000663	\begin{align}
L000664	    &T^0_{\ 0} = -(\overline{\rho} + \delta\rho), &T^0_{\ i} = (\overline{\rho} + \overline{p})(v_i + B_i),  \\
L000665	   & T^i_{\ 0} = -(\overline{\rho} + \overline{p})\,v^i\equiv q^i, &T^i_{\ j} = (\overline{p} + \delta p)\delta^i_j + \Sigma^i_{\ j}.
L000666	\end{align}
L000667	We introduce the scalar part of the 3-velocity and of the 3-momentum~\footnote{We follow the convention of \cite{Peter:2013avv,Baumann:2022mni} where $v_i=\delta_{ij}v^j$. Instead Refs.~\cite{Mukhanov:1990me,Mukhanov:2005sc} define $v_i=-a^2v^i$.}
L000668	\begin{equation}
L000669	    \partial_i( v) \equiv  v_i,\qquad \textrm{and}\qquad  q\equiv (\overline{\rho}+\overline{p})v.
L000670	\end{equation}
L000671	We define the density contrast $\delta \equiv \delta \rho/\rho$.
L000672	
L000673	\textbf{Gauge-invariant quantities ---}
L000674	Under an infinitesimal coordinate transformation generated by scalar functions $T$ and $L$
L000675	\begin{equation}
L000676	\label{eq:coordinate_transformation}
L000677	x^\mu(q)\rightarrow \tilde{x}^\mu(q)\equiv x^\mu(q)+\xi^\mu(q),\quad \textrm{where}\quad \xi^0\equiv T,\quad\textrm{and}\quad \xi^i\equiv \partial^i L,
L000678	\end{equation}
L000679	where $q$ denotes a physical spacetime point, the scalar metric perturbations transform as~\cite{Baumann:2022mni}
L000680	\begin{equation}
L000681	\label{eq:metric_shift}
L000682	    A\rightarrow A-T'-\mathcal{H}T,\quad B\rightarrow B+T-L',\quad C\rightarrow C-\mathcal{H}T-\frac{1}{3}\nabla^2 L,\quad E\rightarrow E-L.
L000683	\end{equation}
L000684	These transformation laws motivate the definition of two gauge-invariant combinations, the Newtonian (or Bardeen) potentials~\cite{Bardeen:1980kt, Baumann:2022mni}:
L000685	\begin{align}
L000686	\label{eq:Bardeen_Potentials}
L000687	    \Psi \equiv A + \mathcal{H}(B - E') + (B - E')', \qquad \Phi \equiv -C + \frac{1}{3}\nabla^2 E - \mathcal{H}(B - E').
L000688	\end{align}
L000689	Under the same coordinate transformation in Eq.~\eqref{eq:coordinate_transformation}, matter perturbations transform as~\cite{Baumann:2022mni}
L000690	\begin{equation}
L000691	\label{eq:matter_shift}
L000692	    \delta \rightarrow \delta-\frac{\overline{\rho}'}{\overline{\rho}} T,\quad \delta p\rightarrow \delta p-\overline{p}'T,\quad v\to v+L',\quad \Sigma_{i j}\rightarrow \Sigma_{ij}.
L000693	\end{equation}
L000694	This in turn motivates the introduction of the following gauge-invariant matter variables~\cite{Peter:2013avv}
L000695	\begin{equation}
L000696	\label{eq:density_constrast_defs}
L000697	   \mathcal{V} \equiv v + E',\quad \delta^{(N)} \equiv \delta + \frac{\overline{\rho}'}{\overline{\rho}}(B - E'),\quad \delta^{(C)}\equiv \delta  + \frac{\overline{\rho}'}{\overline{\rho}}(v+B) ,\quad \delta^{(F)}\equiv \delta+\frac{\overline{\rho}'}{\mathcal{H}\overline{\rho}}\left( -C+\frac{1}{3}\nabla^2E\right).
L000698	\end{equation}
L000699	The quantities $ \delta^{(N)}$, $ \delta^{(C)}$, and  $\delta^{(F)}$ reduce to the contrast density in the Newtonian, comoving and spatially-flat gauges~\footnote{Note that Ref.~\cite{Peter:2013avv} introduces $\delta^{(F)}\equiv \delta-(\overline{\rho}'/\overline{\rho})(C/\mathcal{H})$ instead of $\delta^{(F)}\equiv \delta-(\overline{\rho}'/\overline{\rho})(C/\mathcal{H})+(\overline{\rho}'/\overline{\rho})(\nabla^2E/3\mathcal{H})$ which is however not invariant under the transformation rules in Eq.~\eqref{eq:metric_shift}.}, defined in Eqs.~\eqref{eq:SF_gauge}, \eqref{eq:Newtonian_gauge} and \eqref{eq:Comoving_gauge}, respectively. The quantity $ \mathcal{V}$ reduce to the coordinate velocity $v$ in those three gauges.
L000700	Similarly, we define the gauge-invariant pressure perturbations,
L000701	\begin{equation}
L000702	    \delta p^{(N)} \equiv \delta p + \overline{p}'(B - E'),\quad \delta p^{(C)}\equiv \delta p  + \overline{p}'(v+B) ,\quad \delta p^{(F)} \equiv \delta p+\frac{\overline{p}'}{\mathcal{H}}\left( -C+\frac{1}{3}\nabla^2E\right).
L000703	\end{equation}
L000704	
L000705	\textbf{Linearized Einstein equations ---}
L000706	In the absence of anisotropic stress ($\Sigma^i_{\ j}=0$) the trace-free part of Einstein equations along $ij$ leads to
L000707	\begin{equation}
L000708	\label{eq:no_anisotropy}
L000709	    \Psi = \Phi.
L000710	\end{equation}
L000711	Their expressions in Eqs.~\eqref{eq:Bardeen_Potentials} expressed in the gauges defined in Eqs.~\eqref{eq:SF_gauge}, \eqref{eq:Newtonian_gauge} and \eqref{eq:Comoving_gauge}, are
L000712	\begin{equation}
L000713	\label{eq:Psi_Phi_different_gauges}
L000714	    \Psi =
L000715	    \begin{cases}
L000716	        A, & \\
L000717	        A + \mathcal{H}B + B', &  \\
L000718	        A + \mathcal{H}B + B', & .
L000719	    \end{cases}\qquad  \Phi =
L000720	    \begin{cases}
L000721	        -C, & \text{(Newtonian gauge)}, \\
L000722	        -\mathcal{H}B, & \text{(spatially-flat gauge)}, \\
L000723	        -C - \mathcal{H}B, & \text{(Comoving gauge)}.
L000724	    \end{cases}
L000725	\end{equation}
L000726	The condition in Eq.~\eqref{eq:no_anisotropy} imposes specific relationships among $A$, $B$, and $C$ in different gauges
L000727	\begin{equation}
L000728	\label{eq:Psi_equal_Phi}
L000729	    \Psi=\Phi\quad \Rightarrow \quad\begin{cases}
L000730	    A=-C,\qquad \qquad \qquad \qquad \qquad\qquad\textrm{(Newtonian gauge)},\\
L000731	    A+2\mathcal{H}B+B'=0,\quad \qquad \qquad \qquad\textrm{(Spatially-flat gauge)},\\
L000732	  A+C+2\mathcal{H}B+B'=0,\qquad \qquad \qquad \textrm{(Comoving gauge)}.
L000733	    \end{cases}
L000734	\end{equation}
L000735	The linearised Einstein equations, $00$ component, spatial integration of $0j$ component and trace of $ij$ components, give in the Newtonian gauge, e.g.~\cite{Mukhanov:1990me,Baumann:2022mni}:
L000736	\begin{align}
L000737	    \nabla^2\Phi - 3\mathcal{H}(\Phi' + \mathcal{H}\Phi) &= \frac{3}{2}\mathcal{H}^2\delta^{(N)},\label{eq:Einstein_eq_0_0}\\
L000738	    \Phi' + \mathcal{H}\Phi &= -\frac{3}{2}\mathcal{H}^2 (1+\omega)\mathcal{V},\label{eq:Einstein_eq_0_i}\\
L000739	    \Phi'' + 3\mathcal{H}\Phi' -3\omega\mathcal{H}^2\Phi &= \frac{3}{2}\mathcal{H}^2\frac{\delta p^{(N)}}{\overline{\rho}}.\label{eq:Einstein_eq_i_j}
L000740	\end{align}
L000741	 Combining Eqs.~\eqref{eq:Einstein_eq_0_0} and \eqref{eq:Einstein_eq_i_j}, we obtain the evolution equation for the gauge-invariant Newtonian potential
L000742	\begin{equation}
L000743	\label{eq:Newtonian_potential_evolution_app}
L000744	\Phi'' + 3 (1 + c_s^2)\mathcal{H} \Phi' + (3 (c_s^2-\omega)\mathcal{H}^2-c_s^2 \Delta)\Phi =\frac{3}{2}\mathcal{H}^2 \frac{\delta p_{\rm nad}}{\overline{\rho}},
L000745	\end{equation}
L000746	where we used $\mathcal{H}' = -(1 + 3\omega)\mathcal{H}^2/2$ given by Eq.~\eqref{eq:Friedmann_comoving} and where $\delta p_{\rm nad}$ is the non-adiabatic (or entropic) part of the density perturbation
L000747	\begin{equation}
L000748	\label{eq:delta_nad_app_def}
L000749	    \delta p_{\rm nad}\equiv \delta p-c_s^2\delta \rho,
L000750	\end{equation}
L000751	where $c_s^2$ is the (adiabatic) speed of sound of the universe. It is a background quantity defined by
L000752	\begin{equation}
L000753	\label{eq:SoS}
L000754	c_s^2 \equiv \frac{\delta p}{\delta \rho}\Big|_{\delta p_{\rm nad}=0} = \frac{\overline{p}'}{\overline{\rho}'} = \omega -\frac{\omega'}{3(1+\omega)\mathcal{H}}.
L000755	\end{equation}
L000756	The adiabatic condition $\delta p_{\rm nad}=0$ implies that perturbations correspond to a local time shift of the background, $\eta\to\eta+T(\eta,\mathbf{x})$~\cite{Baumann:2022mni}. To first order, this gives $\delta\rho=\overline{\rho}'\,T$ and $\delta p=\overline{p}'\,T$, yielding the second equality in Eq.~\eqref{eq:SoS}. Another interpretation is that fluctuations in pressure arise solely from fluctuations in density, hence the local equation of state $p(\rho)$ is uniform and $\delta p/\delta \rho = d\overline{p}/d\overline{\rho}$~\cite{Bardeen:1983qw}. The last equality in Eq.~\eqref{eq:SoS} follows from Eqs.~\eqref{eq:EoS} and \eqref{eq:Friedmann_comoving}.
L000757	Combining Eq.~\eqref{eq:Einstein_eq_0_0} and \eqref{eq:Einstein_eq_0_i}, we get the relativistic Poisson equation
L000758	\begin{equation}
L000759	\label{eq:Einstein_eq_00_0i_Poisson}
L000760	    \nabla^2\Phi ~=~ \frac{3}{2}\mathcal{H}^2\delta^{(C)},
L000761	\end{equation}
L000762	where the comoving density contrast $\delta^{(C)}$ is given by the gauge-invariant expressions:
L000763	\begin{align}
L000764	\label{eq:Delta_def}
L000765	    \delta^{(C)}= \delta^{(N)} +2\Phi+\frac{2\Phi'}{\mathcal{H}} =\delta^{(N)}  + \frac{\overline{\rho}'}{\overline{\rho}}\mathcal{V}=\delta  + \frac{\overline{\rho}'}{\overline{\rho}}(v+B) ,
L000766	\end{align}
L000767	with the three equalities being derived from Eqs.~\eqref{eq:Einstein_eq_0_0}, \eqref{eq:Einstein_eq_0_i}, \eqref{eq:density_constrast_defs}, respectively.
L000768	Using Eqs.~\eqref{eq:Bardeen_Potentials},~\eqref{eq:density_constrast_defs} and \eqref{eq:Einstein_eq_0_i}, we deduce the transformation rules between the density contrast in the different gauges
L000769	\begin{align}
L000770	    &\delta^{(C)}-\delta^{(N)}=+2\Phi+\frac{2\Phi'}{\mathcal{H}}, \label{eq:delta_C_delta_N}\\
L000771	    &\delta^{(F)}-\delta^{(N)}=-3(1+\omega)\Phi, \label{eq:delta_F_delta_N}\\
L000772	    &\delta^{(C)}-\delta^{(F)}= (5+3\omega)\Phi +\frac{2\Phi'}{\mathcal{H}}.\label{eq:delta_C_delta_F}
L000773	\end{align}
L000774	We can check that those transformation rules are in agreement with the literature, e.g. \cite[Eqs.~5.87]{Peter:2013avv}.
L000775	The continuity equation in the different gauges are given by
L000776	\begin{align}
L000777	&\delta^{(N)'}+3\mathcal{H}(c_s^2-\omega)\delta^{(N)}=-(1+\omega)(\Delta \mathcal{V}-3\Phi')-3\mathcal{H}\frac{\delta p_{\rm nad}}{\overline{\rho}},\label{eq:delta_N_eq}\\
L000778	&\delta^{(F)'}+3\mathcal{H}(c_s^2-\omega)\delta^{(F)}=-(1+\omega)\Delta \mathcal{V}-3\mathcal{H}\frac{\delta p_{\rm nad}}{\overline{\rho}},\label{eq:delta_F_eq}\\
L000779	&\delta^{(C)'}-3\omega\mathcal{H}\delta^{(C)}=-(1+\omega)\Delta \mathcal{V}.\label{eq:delta_C_eq}
L000780	\end{align}
L000781	The first equation in Eq.~\eqref{eq:delta_N_eq} can be calculated from a combination of Eq.~\eqref{eq:Einstein_eq_0_0} and its derivative. The second equation in Eq.~\eqref{eq:delta_F_eq} can be deduced from the first using Eq.~\eqref{eq:delta_F_delta_N}. The third equation in Eq.~\eqref{eq:delta_C_eq} can be derived from taking the derivative of Eq.~\eqref{eq:Einstein_eq_00_0i_Poisson}, using Eq.~\eqref{eq:Einstein_eq_0_i} and finally using Eq.~\eqref{eq:Einstein_eq_00_0i_Poisson} again. The first two equations are also given in \cite[Eqs.~5.125 and 5.128]{Peter:2013avv}.
