L000785	\subsection{Gauge-invariant curvature perturbations}
L000786	We can introduce two additional gauge-invariant quantities to express curvature perturbations. At first the comoving curvature perturbation $\mathcal{R}$~\cite{Bardeen:1980kt}
L000787	\begin{align}
L000788	\mathcal{R} ~\equiv ~ -C+\frac{1}{3}\nabla^2E-\mathcal{H}(v+B) ~=~\Phi - \mathcal{H}\mathcal{V} ~=~ \frac{5+3\omega}{3+3\omega} \Phi +\frac{2\Phi'}{3(1+\omega)\mathcal{H}},
L000789	\label{eq:mathcalR_def}
L000790	\end{align}
L000791	where the third equality follows from Eq.~\eqref{eq:Einstein_eq_0_i}.
L000792	The curvature perturbation on uniform density hypersurface $\zeta$~\cite{Bardeen:1983qw,Wands:2000dp,Lyth:2004gb}:
L000793	\begin{equation}
L000794	\label{eq:zeta_def}
L000795	\zeta ~\equiv ~ -C+\frac{1}{3}\nabla^2E+\mathcal{H}\frac{\overline{\rho}}{\overline{\rho}'}\delta ~=~ \Phi-\frac{1}{3}\frac{\delta^{(N)}}{1+\omega} = -\frac{1}{3}\frac{\delta^{(F)}}{1+\omega} ~=~ \mathcal{R}-\frac{\delta^{(C)}}{3(1+\omega)},
L000796	\end{equation}
L000797	where the third and fourth equalities follow from Eqs.~\eqref{eq:delta_F_delta_N} and \eqref{eq:delta_C_delta_F}. Those two gauge-invariant quantities, $\mathcal{R}$  and $\zeta$,  are particularly convenient due to their laws of conservation. Using $\mathcal{H}' = -(1+3\omega)\mathcal{H}/2$, $\omega'=-3\mathcal{H}(1+\omega)(c_s^2-\omega)$, Eq.~\eqref{eq:Einstein_eq_0_i} and Eq.~\eqref{eq:Newtonian_potential_evolution_app}, we calculate
L000798	\begin{align}
L000799	\label{eq:R_prime_Phi_prime}
L000800	\mathcal{R}' ~=~  \mathcal{H} \frac{\delta p_{\rm nad}}{\overline{\rho}+\overline{p}} - \frac{2c_s^2}{3(1+\omega)}\frac{k^2}{\mathcal{H}}\Phi,\qquad \textrm{and} \qquad\zeta' ~= ~ \mathcal{H} \frac{\delta p_{\rm nad}}{\overline{\rho}+\overline{p}} - \frac{k^2 \mathcal{V}}{3}.
L000801	\end{align}
L000802	The Fourier index $k$ is suppressed for clarity.
L000803	In the absence of large-scale non-adiabatic pressure fluctuation $\delta p_{\rm nad}=0$, the curvature perturbations are conserved $\mathcal{R}'\simeq \zeta'\simeq 0$ on super-horizon scales $k\ll \mathcal{H}$. Plugging $\delta p_{\rm nad}=0$ and $c_s^2\simeq \omega$ into Eq.~\eqref{eq:Newtonian_potential_evolution_app}, we deduce that the Newtonian potential is also conserved  $\Phi'\simeq 0$ for adiabatic evolution and super-horizon scales.
L000804	For constant Newtonian potential $\Phi'\simeq 0$, Eqs.~\eqref{eq:Einstein_eq_00_0i_Poisson}, \eqref{eq:delta_C_delta_N}, \eqref{eq:delta_F_delta_N}, \eqref{eq:delta_C_delta_F}, and \eqref{eq:mathcalR_def}  lead to
L000805	\begin{equation}
L000806	\label{eq:R_relations}
L000807	-\mathcal{R}\simeq -\left( \frac{5+3\omega}{3+3\omega} \right)\Phi \simeq  \frac{5+3\omega}{2(1+\omega)}\left(\frac{\mathcal{H}}{k}\right)^2\delta^{(C)}\simeq\frac{5+3\omega}{1+\omega}\frac{\left(\mathcal{H}/k\right)^2\delta^{(F)}}{2+3(5+3\omega)(\mathcal{H}/k)^2}\simeq\frac{5+3\omega}{2(1+\omega)}\frac{\left(\mathcal{H}/k\right)^2\delta^{(N)}}{1+3(\mathcal{H}/k)^2}.
L000808	\end{equation}
L000809	Using Eqs.~\eqref{eq:zeta_def}, we deduce
L000810	\begin{equation}
L000811	\label{eq:zeta_relations}
L000812	-\zeta  \simeq  \frac{(2+3(5+3\omega)(\mathcal{H}/k)^2)}{6(1+\omega)}\delta^{(C)}\simeq \frac{\delta^{(F)}}{3(1+\omega)}\simeq\frac{(2+3(\mathcal{H}/k)^2(5+3\omega)}{6(1+\omega)(1+3(\mathcal{H}/k)^2)}\delta^{(N)},
L000813	\end{equation}
L000814	as well as
L000815	\begin{equation}
L000816	\label{eq:R_zeta_relations}
L000817	    \zeta \simeq  \frac{(2+3(5+3\omega)(\mathcal{H}/k)^2)}{3(5+3\omega)(\mathcal{H}/k)^2}\mathcal{R}.
L000818	\end{equation}
L000819	We recover the well-known result that $\zeta \simeq \mathcal{R}$ in the super-horizon limit $k\ll \mathcal{H}$ in the absence of large-scale non-adiabatic pressure perturbation.
L000820	Eq.~\eqref{eq:R_relations}, \eqref{eq:zeta_relations}, and \eqref{eq:R_zeta_relations} become exact in the limit $\Phi' \to 0$.
L000821	Evaluating those expression at horizon crossing $\mathcal{H}=k$ and assuming a radiation-dominated universe $\omega=1/3$, we obtain
L000822	\begin{align}
L000823	\label{eq:R_relations_rad}
L000824	 -\mathcal{R}~\simeq~ -\frac{9}{10}\zeta~\simeq~ -\frac{3}{2}\Phi~ \simeq  ~ \frac{9\delta^{(F)}}{40}~\simeq~ \frac{9}{16}\delta^{(N)}~ \simeq ~ \frac{9}{4}\delta^{(C)} .
L000825	\end{align}
L000826	Fig.~\ref{fig:Variance_betaOH4_perturbations} (right) shows that the adiabatic and horizon-entry approximations in Eq.~\eqref{eq:R_relations_rad} remain accurate during
L000827	a first-order phase transition, except for modes entering the horizon near
L000828	percolation, $k \sim k_{\rm max}$, due to violation of the non-adiabaticity condition $\delta p_{\rm nad}\neq 0$.
