L001101	\subsection{Scalar-induced gravitational waves}
L001102	
L001103	SIGWs generated at second order in cosmological perturbation theory are given by
L001104	\cite{Tomita:1975kj,Matarrese:1992rp,Matarrese:1993zf,Matarrese:1997ay,Acquaviva:2002ud,Mollerach:2003nq,Carbone:2004iv,Ananda:2006af,Baumann:2007zm,Espinosa:2018eve,Kohri:2018awv,Domenech:2021ztg}
L001105	\begin{equation}
L001106	\Omega_{\rm SIGW}(k,\eta)
L001107	= \frac{1}{24}
L001108	\left(\frac{k}{{\cal H}(\eta)}\right)^2
L001109	\overline{{\cal P}_h(k,\eta)} \,,
L001110	\label{eq:OmegaGW}
L001111	\end{equation}
L001112	where $\overline{{\cal P}_h}$ denotes the oscillation-averaged tensor power spectrum \cite{Maggiore:1999vm}.
L001113	The induced tensor spectrum is
L001114	\begin{align}
L001115	\overline{{\cal P}_h(k,\eta)}\,
L001116	(2\pi)^3 \delta_D^{(3)}(\mathbf{k}+\mathbf{k}')
L001117	&=
L001118	\frac{16 k^3}{2\pi^2}
L001119	\sum_s
L001120	\int \frac{d^3\mathbf{p}}{(2\pi)^3}
L001121	\int \frac{d^3\mathbf{q}}{(2\pi)^3}
L001122	\nonumber\\
L001123	&\hspace{-1.2cm}\times
L001124	\overline{
L001125	J_s(\mathbf{k},\mathbf{p},\eta)
L001126	J_s(\mathbf{k}',\mathbf{q},\eta)
L001127	}
L001128	\,
L001129	\big\langle
L001130	\mathcal{R}_{\mathbf{p}}
L001131	\mathcal{R}_{\mathbf{k}-\mathbf{p}}
L001132	\mathcal{R}_{\mathbf{q}}
L001133	\mathcal{R}_{\mathbf{k}'-\mathbf{q}}
L001134	\big\rangle \,,
L001135	\label{eq:Phfull_app}
L001136	\end{align}
L001137	where $s$ labels the two GW polarizations.
L001138	The kernel
L001139	\begin{equation}
L001140	J_s(\mathbf{k},\mathbf{p},\eta)
L001141	\equiv Q_s(\mathbf{k},\mathbf{p})\, I(\mathbf{k},\mathbf{p},\eta)
L001142	\end{equation}
L001143	is the product of the polarization contraction
L001144	$Q_s(\mathbf{k},\mathbf{p})=e^{ij}_s(\hat{\mathbf{k}})p_ip_j$
L001145	and the time-dependent convolution of the source with the Green function,
L001146	$I(\mathbf{k},\mathbf{p},\eta)$.
L001147	Explicit expressions can be found in
L001148	Refs.~\cite{Espinosa:2018eve,Kohri:2018awv,LISACosmologyWorkingGroup:2025vdz}.
L001149	For Gaussian curvature perturbations, only disconnected Wick contractions contribute to the four-point function in Eq.~\eqref{eq:Phfull_app}.
L001150	In the presence of primordial non-Gaussianities (NGs), additional disconnected contributions arise, together with genuinely connected terms proportional to the curvature trispectrum
L001151	\cite{Nakama:2016gzw,Garcia-Bellido:2017aan,Unal:2018yaa,Cai:2018dig,Cai:2019amo,Ragavendra:2020sop,Yuan:2020iwf,Adshead:2021hnm,Davies:2021loj,Abe:2022xur,Garcia-Saenz:2022tzu,Garcia-Saenz:2023zue,Li:2023xtl,Yuan:2023ofl,Perna:2024ehx,Gouttenoire:2025jxe}.
L001152	
L001153	We quantify the level of NG by the skewness of the curvature perturbation,
L001154	\cite{Luo:1992er,Komatsu:2001rj}
L001155	\begin{equation}
L001156	F_{\rm NL}
L001157	\equiv
L001158	\frac{\langle \mathcal{R}^3 \rangle}
L001159	{6 \langle \mathcal{R}^2 \rangle^2} \,.
L001160	\end{equation}
L001161	As shown in Fig.~\ref{fig:Negative_fNL} (left), $F_{\rm NL}$ exhibits a scale dependence.
L001162	Since the SIGW signal is dominated by modes near the peak of the scalar power spectrum, we evaluate $F_{\rm NL}$ at
L001163	$k\simeq 0.9\,k_{\rm max}$.
L001164	For $\beta_H\equiv \beta/H \in [2,15]$, we find the empirical fit
L001165	\begin{equation}
L001166	\log_{10} F_{\rm NL}
L001167	\simeq
L001168	a \log_{10}^2(\beta_H/b)
L001169	+ c \log_{10}(\beta_H/b) \,,
L001170	\end{equation}
L001171	with $a\simeq -1.34$, $b\simeq 3.67$, and $c\simeq 2.95$.
L001172	
L001173	The present-day SIGW spectrum can be decomposed as~\cite{Inomata:2019yww,DeLuca:2019ufz,Yuan:2019fwv,Domenech:2020xin} \begin{equation}\label{eq:Omegabar-total} \Omega_{\rm SIGW} =\Omega_{\rm SIGW}^{(0)} +\Omega_{\rm SIGW}^{(1)} +\Omega_{\rm SIGW} ^{(2)} \ , \end{equation} \begin{align} \Omega_{\rm SIGW}^{(0)} = \frac{1}{3} \int_1^\infty \td t \int_{-1}^1 \td s \frac{\overline{J^2(u,v)}}{(u v)^2} {\cal P}_\mathcal{R} (v k) {\cal P}_\mathcal{R} (u k) , \label{eq:P_h_ts} \end{align} where $u=(t + s)/2$, $v=(t - s)/2$ and the transfer function $\overline{J^2 (u,v)}$ depends on the cosmological background~\cite{Kohri:2018awv,Espinosa:2018eve}. In accordance with Refs.~\cite{Adshead:2021hnm, Li:2023qua, Zhu:2023faa, Ragavendra:2021qdu, Atal:2021jyo}, the higher-order terms in \eqref{eq:Omegabar-total} can be expressed as \begin{align} \Omega_{\rm SIGW}^{(1)} =& \frac{2F_{\rm NL}^2}{3} \prod_{i=1}^2 \biggl[\int_1^\infty \td t_i \int_{-1}^1 \td s_i\, u_iv_i\biggr] \Bigg\{ \frac{1}{2} \overline{J^2 (s_1,t_1)} \frac{ {\cal P}_\mathcal{R} (v_1 v_2 k) {\cal P}_\mathcal{R} (u_1 k) {\cal P}_\mathcal{R} (v_1 u_2 k)}{(u_1v_1u_2v_2)^3} \nonumber \\ +& \int_0^{2\pi} \frac{\td \varphi_{12}}{2\pi}\, \cos 2\varphi_{12} \overline{J (s_1,t_1) J (s_2,t_2)} \frac{{\cal P}_\mathcal{R} (v_2 k)}{v_2^3} \frac{{\cal P}_\mathcal{R} (w_{12} k)}{w_{12}^3} \bigg[ \frac{{\cal P}_\mathcal{R} (u_2 k)}{u_2^3} + \frac{{\cal P}_\mathcal{R} (u_1 k)}{u_1^3} \bigg] \Bigg\} \label{eq:Omega-C} \end{align} and \begin{align} \label{eq:Omega-N} \Omega_{\rm SIGW}^{(2)} &= \frac{F_{\rm NL}^4}{6} \prod_{i=1}^3 \biggl[\int_1^\infty \td t_i \int_{-1}^1 \td s_i\, u_iv_i\biggr] \Bigg\{\frac{1}{2}\overline{J^2 (s_1,t_1)} \frac{{\cal P}_\mathcal{R} (v_1 v_2 k) {\cal P}_\mathcal{R} (v_1 u_2 k) {\cal P}_\mathcal{R} (u_1 v_3 k) {\cal P}_\mathcal{R} (u_1 u_3 k)}{(u_1v_1u_2v_2u_3v_3)^3} \\ & + \int_0^{2\pi} \frac{\td \varphi_{12}}{2\pi}\frac{\td \varphi_{23}}{2\pi} \cos (2\varphi_{12} ) \overline{J (s_1,t_1) J (s_2,t_2)} \frac{{\cal P}_\mathcal{R}(u_3 k)}{u_3^3} \frac{{\cal P}_\mathcal{R} (w_{13} k)}{w_{13}^3} \frac{{\cal P}_\mathcal{R} (w_{23} k)}{w_{23}^3} \bigg[ \frac{{\cal P}_\mathcal{R} (v_3 k)}{v_3^3} + \frac{{\cal P}_\mathcal{R} (w_{123} k)}{w_{123}^3} \bigg]\Bigg\} \ , \nonumber \end{align} where we defined $s_i=u_i-v_i$, $t_i=u_i+v_i$, and \begin{subequations} \begin{eqnarray} y_{ij}&=&\frac{\cos\varphi_{ij}}{4}\sqrt{(t_i^2-1)(t_j^2-1)(1-s_i^2)(1-s_j^2)}+\frac{1}{4}(1-s_it_i)(1-s_jt_j)\ , \\ w_{ij}&=&\sqrt{v_i^2+v_j^2-y_{ij}}\, , \qquad w_{123}=\sqrt{v_1^2+v_2^2+v_3^2+y_{12}-y_{13}-y_{23}},\qquad \varphi_{13}=\varphi_{12}-\varphi_{23}.\ . \end{eqnarray} \end{subequations} The time-averaged integrated transfer functions $J(u,v)$ were derived in Refs.~\cite{Espinosa:2018eve,Kohri:2018awv,Atal:2021jyo,Adshead:2021hnm,Li:2023qua}, and are \begin{align}\label{eq:J-ave-12} & \overline{ J (s_i,t_i)J (s_j,t_j) } = \frac{9}{8}\frac{\left(t_i^2-1\right) \left(t_j^2-1\right) \left(1-s_i^2\right) \left(1-s_j^2\right) \left(t_i^2+s_i^2-6\right) \left(t_j^2+s_j^2-6\right) }{\left(t_i^2-s_i^2\right)^3 \left(t_j^2-s_j^2\right)^3} \nonumber\\ & \Bigg[ \left( \left(t_i^2+s_i^2-6\right) \ln \left| \frac{t_i^2-3}{3-s_i^2}\right| - 2\left(t_i^2-s_i^2\right) \right) \left( \left(t_j^2+s_j^2-6\right) \ln \left| \frac{t_j^2-3}{3-s_j^2}\right| - 2\left(t_j^2-s_j^2\right) \right) \nonumber\\ & + \pi^2\Theta\left(t_i-\sqrt{3}\right) \Theta\left(t_j-\sqrt{3}\right) \left(t_i^2+s_i^2-6\right) \left(t_j^2+s_j^2-6\right) \Bigg]\ . \end{align}
L001174	The contribution of scalar-induced gravitational waves to the total gravitational-wave signal from the first-order phase transition is shown in the main text to be numerically negligible,
L001175	$\Omega_{\rm SIGW} \ll \Omega_{\rm PGW}$.
L001176	As a consequence, the impact of primordial non-Gaussianities on the SIGW spectrum is also negligible,
L001177	$\Omega_{\rm SIGW}^{(1)},\,\Omega_{\rm SIGW}^{(2)} \ll \Omega_{\rm SIGW}^{(0)}$,
L001178	as illustrated in Fig.~\ref{fig:Negative_fNL} (right).
L001179	
L001180	This behavior is expected on parametric grounds:
L001181	a suppressed SIGW contribution,
L001182	$\Omega_{\rm SIGW}/\Omega_{\rm PGW}\sim \langle \mathcal{R}^2\rangle$,
L001183	implies correspondingly small non-Gaussian corrections,
L001184	$\Omega_{\rm SIGW}^{(1)}/\Omega_{\rm SIGW}^{(0)}\sim F_{\rm NL}^2\langle \mathcal{R}^2\rangle$
L001185	and
L001186	$\Omega_{\rm SIGW}^{(2)}/\Omega_{\rm SIGW}^{(0)}\sim F_{\rm NL}^4\langle \mathcal{R}^2\rangle^2$.
